#include "cipheropbench/decoder.cuh"
#include <fstream>
#include <iostream>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace cipheropbench;
bool benchmark(Runtime& r,const std::string& scope,int tokens,int runs,int warmup,const char* output,int input_bits=40){
 DecoderOperators ops(r);bool arion=scope.starts_with("arion_"),silu=scope=="swiglu"||scope=="arion_swiglu",norm=scope=="rmsnorm"||scope.starts_with("arion_rmsnorm"),exponential=scope=="arion_exp",inverse=scope=="arion_inverse",attention=exponential||inverse;int kind=norm&&arion?scope.back()-'0':0;
 int width=attention?8192:silu?14336:scope=="rope_k"?1024:4096;auto x=torch::sin(torch::arange(tokens*width,torch::kDouble)*.013).reshape({tokens,width})*(exponential?1.4:inverse?16.:silu?3.:kind==1?.01:.1)+(exponential?-2.6:inverse?32.:scope=="rmsnorm"?1.:0.);auto up=x*.1+.2;auto a=ops.encrypt_rows(x,std::ldexp(1.,input_bits)),b=silu?ops.encrypt_rows(up):DecoderRows{};DecoderRows out;auto gamma=torch::linspace(.8,1.2,4096,torch::kDouble);
 auto evaluate=[&]{if(exponential)out=ops.arion_exp(a);else if(inverse)out=ops.arion_inverse(a);else if(silu)out=ops.swiglu(a,b);else if(norm)out=ops.rmsnorm(a,gamma,1e-5,kind);else out=ops.rope(a,17);};
 std::vector<double> samples;for(int i=-warmup;i<runs;++i){out={};r.synchronize();auto start=std::chrono::steady_clock::now();evaluate();r.synchronize();if(i>=0)samples.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());}
 auto actual=ops.decrypt_rows(out);torch::Tensor expected;
 if(exponential)expected=x.exp();else if(inverse)expected=x.reciprocal();else if(silu)expected=x*torch::sigmoid(x)*up;else if(norm)expected=x*torch::rsqrt(x.square().mean(-1,true)+1e-5)*gamma;
 else{auto z=x.reshape({tokens,-1,64,2});auto angle=torch::arange(17,17+tokens,torch::kDouble).reshape({-1,1,1})*torch::pow(500000.,-torch::arange(0,128,2,torch::kDouble)/128).reshape({1,1,64});auto u=z.select(-1,0),v=z.select(-1,1);expected=torch::stack({u*angle.cos()-v*angle.sin(),u*angle.sin()+v*angle.cos()},-1).reshape_as(x);}
 auto error=(actual-expected).abs();bool passed=torch::isfinite(actual).all().item<bool>()&&error.max().item<double>()<(attention?.002:.01)&&error.mean().item<double>()<(attention?.0001:.001);auto sorted=samples;std::sort(sorted.begin(),sorted.end());double median=sorted.size()%2?sorted[sorted.size()/2]:(sorted[sorted.size()/2-1]+sorted[sorted.size()/2])/2;
 std::ofstream f(output,std::ios::app);TORCH_CHECK(f,"Cannot write decoder benchmark output");cudaDeviceProp device;cudaGetDeviceProperties(&device,0);f<<std::setprecision(12)<<"{\"schema_version\":1,\"method\":\""<<(arion?"arion":"decoder_common")<<"\",\"scope\":\""<<scope<<"\",\"tokens\":"<<tokens<<",\"width\":"<<width<<",\"active_samples\":1,\"N\":65536,\"log_scale\":"<<input_bits<<",\"gpu\":\""<<device.name<<"\",\"input_encryption\":\""<<Runtime::input_encryption_mode()<<"\",\"status\":\""<<(passed?"validated":"numerical_mismatch")<<"\",\"evidence\":\"measured_controlled_decoder_primitive\",\"native_method_decoder\":false,\"threads\":2,\"input_fixture\":\"controlled_sine\",\"arithmetic_profile\":\""<<(attention?(input_bits==45?"arion_input45_normalize40_exp63_work80_inverse255_ps16_newton2_row_v8":"arion_exp63_work80_inverse255_ps16_newton2_row_v4"):arion?"arion_release_nonlinear_new_row_packing":"common_controlled_rms31_newton2_silu127")<<"\",\"layout\":\"row_contiguous_power_of_two_stride\",\"key_profile\":\""<<(attention?"elementwise_only_conjugation":"positive_radix4_rotations")<<"\",\"security\":\"functional_backend_security_unverified\",\"timing_boundary\":\"server_evaluation_excludes_keys_encrypt_decrypt\",\"runs\":"<<runs<<",\"warmup\":"<<warmup<<",\"median_ms\":"<<median<<",\"max_abs_error\":";
 double maximum=error.max().item<double>(),mean=error.mean().item<double>();if(std::isfinite(maximum))f<<maximum;else f<<"null";f<<",\"mae\":";if(std::isfinite(mean))f<<mean;else f<<"null";
 if(attention)f<<",\"input_normalization_plain_multiplications\":"<<(input_bits==45?1:0)<<",\"input_levels\":31,\"output_levels\":"<<out.blocks[0].coeff_modulus_size()<<",\"polynomial_degree\":"<<(inverse?255:63)<<",\"polynomial_evaluator\":\""<<(inverse?"dyadic_ps_baby16":"full_chebyshev_basis")<<"\",\"polynomial_work_scale_bits\":"<<(inverse?40:80)<<",\"output_scale_bits\":40,\"newton_steps\":"<<(inverse?2:0)<<",\"heads_per_call\":1,\"bootstrap_included\":false,\"global_normalization_included\":false";
 f<<",\"coeff_modulus_bits\":[51";for(int i=0;i<16;++i)f<<",40";for(int i=0;i<15;++i)f<<",51";f<<"],\"samples_ms\":[";for(size_t i=0;i<samples.size();++i){if(i)f<<',';f<<samples[i];}f<<"]}\n";std::cout<<scope<<" median_ms="<<median<<" "<<(passed?"validated":"numerical_mismatch")<<std::endl;return passed;
}
int main(int argc,char** argv){try{
 TORCH_CHECK(argc==6,"usage: cipheropbench_decoder_bench SCOPE|all|arion|arion_attention|arion_attention45 TOKENS RUNS WARMUP OUTPUT_JSONL");std::string scope=argv[1];int tokens=std::stoi(argv[2]),runs=std::stoi(argv[3]),warmup=std::stoi(argv[4]);TORCH_CHECK(tokens>0&&tokens<=128&&runs>0&&warmup>=0,"Invalid decoder benchmark workload");TORCH_CHECK(scope=="all"||scope=="arion"||scope=="arion_attention"||scope=="arion_attention45"||scope=="arion_exp"||scope=="arion_inverse"||scope=="swiglu"||scope=="rmsnorm"||scope=="rope_q"||scope=="rope_k"||scope=="arion_rmsnorm1"||scope=="arion_rmsnorm2"||scope=="arion_swiglu","Unknown decoder benchmark scope");bool attention=scope=="arion_attention"||scope=="arion_attention45"||scope=="arion_exp"||scope=="arion_inverse";if(attention){const char* keys=std::getenv("CIPHEROPBENCH_ELEMENTWISE_ONLY");TORCH_CHECK(keys&&std::string(keys)=="1"&&!std::getenv("CIPHEROPBENCH_DECODER_ONLY"),"Standalone attention nonlinear timing requires elementwise keys");}torch::set_num_threads(2);torch::NoGradGuard guard;Runtime r(false);bool passed=true;
 for(const auto& s:scope=="all"?std::vector<std::string>{"rope_q","rope_k","rmsnorm","swiglu"}:scope=="arion"?std::vector<std::string>{"arion_rmsnorm1","arion_rmsnorm2","arion_swiglu"}:(scope=="arion_attention"||scope=="arion_attention45")?std::vector<std::string>{"arion_exp","arion_inverse"}:std::vector<std::string>{scope})passed=benchmark(r,s,tokens,runs,warmup,argv[5],scope=="arion_attention45"?45:40)&&passed;return passed?0:1;
}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
